def middle(image_patch: ImagePatch) -> ImagePatch:
    """Returns the middle ImagePatch object."""
    width, height = image_patch.cropped_image.shape[:2]
    center_x, center_y = width // 2, height // 2
    return image_patch.crop(center_x - width // 4, center_y - height // 4, center_x + width // 4, center_y + height // 4)

